import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/LenovoTabP12.html","title":"LenovoTabP12","lang":"en-US","frontmatter":{},"git":{"createdTime":1759028739000,"updatedTime":1759318871000,"contributors":[{"name":"Kazuma Arino","username":"","email":"hogeika2@gmail.com","commits":4}]},"readingTime":{"minutes":3.19,"words":956},"filePathRelative":"LenovoTabP12.md"}`),a={name:`LenovoTabP12.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="lenovotabp12" tabindex="-1"><a class="header-anchor" href="#lenovotabp12"><span>LenovoTabP12</span></a></h1><p><a href="./タブレット.html">タブレット</a></p><p><a href="https://www.lenovo.com/jp/ja/p/tablets/lenovo-tab-series/lenovo-tab-p12/len103l0018?srsltid=AU7gw4W1BU4VY90HAAeOl3qYxttpOQjzqWXDS6L_hDQwb0EystBJYflc" target="_blank" rel="noopener noreferrer">Lenovo Tab P12 - 広い画面でパワフルな性能を楽しむ - レノボ・ ジャパン</a></p><p><a href="./KindleFire.html">KindleFire</a>Maxがちょっと狭く感じるようになってきたし、 あまり持ち歩かないので、もう少し大きいタブレットでいいのではないか？と思って調べていきついたタブレット。</p><ul><li>12.7インチ</li><li>2944x1840</li><li>アスペクト比 16:10 (iOSは4:3）</li><li><a href="https://en.wikipedia.org/wiki/Quick_Charge" target="_blank" rel="noopener noreferrer">Quick Charge - Wikipedia</a></li><li>615g</li></ul><h2 id="購入-2025-09-30-火" tabindex="-1"><a class="header-anchor" href="#購入-2025-09-30-火"><span>購入 2025-09-30 (火)</span></a></h2><p><a href="https://hb.afl.rakuten.co.jp/ichiba/4cdcea13.76ef106e.4cdcea14.60942c00/?pc=https%3A%2F%2Fitem.rakuten.co.jp%2Flenovopc%2Fzach0002jp%2F&amp;link_type=pict&amp;ut=eyJwYWdlIjoiaXRlbSIsInR5cGUiOiJwaWN0Iiwic2l6ZSI6IjI0MHgyNDAiLCJuYW0iOjEsIm5hbXAiOiJyaWdodCIsImNvbSI6MSwiY29tcCI6ImRvd24iLCJwcmljZSI6MSwiYm9yIjoxLCJjb2wiOjEsImJidG4iOjEsInByb2QiOjAsImFtcCI6ZmFsc2V9" target="_blank" rel="nofollow sponsored noopener" style="word-wrap:break-word;"><img src="https://hbb.afl.rakuten.co.jp/hgb/4cdcea13.76ef106e.4cdcea14.60942c00/?me_id=1259632&amp;item_id=10005656&amp;pc=https%3A%2F%2Fthumbnail.image.rakuten.co.jp%2F%400_gold%2Flenovopc%2Fimages%2Fthumbnail-1%2Fdefault%2Fzach0002jp-1.jpg%3F_ex%3D240x240&amp;s=240x240&amp;t=pict" border="0" style="margin:2px;" alt="" title=""><br> 12.7インチ Lenovo Tab P12</a></p><p>楽天スーパーDEALで10%ポイント還元だったので、44980円+6700ポイントだった。0のつく日の1倍が入ってない気がするので、ひょっとしたらあとからもうちょっとポイントがつくかも？ 6700ポイントとしても3.8万ちょいなので結構いい気はする。</p><p>スタイラスは別売りで楽天では9000円くらい、Amazonだと6000円くらいだった。とりあえず保留。</p><h2 id="到着、ファーストインプレッション-2025-10-03-金" tabindex="-1"><a class="header-anchor" href="#到着、ファーストインプレッション-2025-10-03-金"><span>到着、ファーストインプレッション 2025-10-03 (金)</span></a></h2><p>9:00に最寄りの営業所を出ていながら到着は15:40で結構やきもきしたが、無事届いたので設定。</p><p>開幕にAppServicesとかいうのがTikTokとかTemuとかロイヤルマッチとかいろいろ入れようとしてきて、しかもスキップ出来ない！すげー印象悪いが、 設定から無効にしてしまって事なきを得る。</p><p>Googleもいろいろいらないの入れてこようとして感じ悪い。 Google Podcastのインストールがスキップ出来ない！なんなの！？お前サービスもうやめてるくせに！ という事で使わないGoogleサービスをいろいろ無効にしたりする。</p><p>そういう不愉快さはあるけれど、Androidとしては割と素のAndroidに近いので、その辺さえ回避すれば割とクセはない。</p><p>付属の充電器は充電が遅いなぁ、という事で手持ちのMacBookの予備に使ってる高速充電出来る奴を試すと3倍くらいの4倍位の速度で充電される。付属の充電器ダメじゃん。</p><h3 id="画面の大きさの印象はmixed" tabindex="-1"><a class="header-anchor" href="#画面の大きさの印象はmixed"><span>画面の大きさの印象はmixed</span></a></h3><p>動画は結構画面大きいな、と思う。youtubeとかすごくいい感じ。</p><p>一方でDolyで<a href="./たてなか流クイックスケッチ.html">たてなか流クイックスケッチ</a>とかを見ると結構小さいと感じる。上下の余白があって画面サイズを活かしきれてない、という要素もあるが、 大きすぎるという事は無いなぁ、という印象。 ただ余白が消えるように拡大すると、まぁまぁのサイズになる。 アスペクト比は4:3の方がいいかもなぁ。</p><p>ただYouTubeはこの比率の方がいい。悩ましいね。 サーフィン動画には凄くいい感じ。大迫力。 一方で将棋とか囲碁を見るには無駄にでかいな、と思う。こういう動画のときには取り回しの悪さの方が気になる。</p><p>デカすぎて端が見えないとか重すぎるとかいうレビューも結構あったが、老眼世代には大きすぎるという事は無いな。</p><p>思ったよりも持って使えるな。下に置かないとダメかと思ったが、あまりこれまでの運用と変わらない気がする。11インチだって片手で持ってると重いしね。 ただ11インチの方が取り回しは良いな。</p><p>そして音はいい感じにステレオだな。物理的にスピーカー同士の距離があって、ステレオ感が強い。</p><p>ピッコマのSmartoon向きでは無いな。スクロールがかったるい。こういうの読むにはでかすぎるな。 ただピッコマが動くのはいいね。普通のAndroidタブレット万歳。</p><h3 id="タスクバーのカスタマイズがsystem-launcherでしか出来ない" tabindex="-1"><a class="header-anchor" href="#タスクバーのカスタマイズがsystem-launcherでしか出来ない"><span>タスクバーのカスタマイズがSystem Launcherでしか出来ない</span></a></h3><p>ホーム画面にこれまであったアプリのショートカットみたいなのがあるのだが、これがSystem Launcherのときだけはホーム以外でも3ボタンナビゲーションに出たままになる。 これは結構便利で、ホームに戻らずに好きなアプリが起動出来る。</p><p>でもMicrosoft LauncherとかNova Launcherにするとここがカスタマイズできなくなる。（その事実に気づくのに結構時間がかかった）</p><h3 id="バッテリはまぁまぁ減るが充電は早い" tabindex="-1"><a class="header-anchor" href="#バッテリはまぁまぁ減るが充電は早い"><span>バッテリはまぁまぁ減るが充電は早い</span></a></h3><p>昼飯をだらだら食べながら動画を見ていると、100%が90%くらいになる。 100%の状態から夜寝ながら動画見て、朝飯を食べつつ動画を見ていると80%くらいになる。 ちょっとバッテリの保ちは悪いな、という印象。</p><p>ただ充電は早い。30分くらい充電しておけば満充電になっている感じだ。食事のあとに充電しておいて歯磨きとかして少しなにかしていれば満充電に戻っている。</p><p>同梱の充電器は遅い気がするがググったら20Wと出ていた。ほんまかいな、という気もするが、このタブレット自体は30Wに対応しているらしいので、 30W充電対応の充電器も買うかなぁ。＞<a href="./USB充電器.html">USB充電器</a></p><h3 id="しばらく使っての感想-2025-10-26-日" tabindex="-1"><a class="header-anchor" href="#しばらく使っての感想-2025-10-26-日"><span>しばらく使っての感想 2025-10-26 (日)</span></a></h3><p>割と日常の一部になってきたので、現在の印象など。</p><p>まず、web小説などを寝なら読むには、大きすぎていまいちではあるが使えなくはない。特に縦で読むのはいまいち。 ただ横で読むには結構いい事もある。</p><p>全体的に、縦に置くと通常のスマホスタンドでは不安定で、これが大きすぎる一番のデメリットという気がする。いい感じのスタンドを常備出来たら変わるかもしれない。</p><p>web小説は<a href="./KindleFire.html">KindleFire</a> Maxの方が良くて、たまにKindleFire Maxを引っ張り出してきて読む事もある。KindleFire Maxはweb小説読むのにちょうどいいな。 Lenovo Tab P12を使うようになってかえってKindleFire Maxの評価が上がった部分だ。</p><p>YouTubeは最大化しないでウィンドウ状態で見ても十分な動画が結構あり、これが意外と便利だ。 画面サイズがいらない動画はかえって大画面の利点が活きる。</p><p>ピッコマなどを読むには特に不満は無い。最初はでかすぎてスクロールがかったるいと思っていたがすぐに適応した。 やはりピッコマが読めるのはいいよな。</p><p>スペック的には満足している。十分。いい感じ。画面綺麗だよなぁ。そして素のAndroidなのはいいよな。FireOSとの違いを感じる。</p><p>画面の大きさはもっと大きい方がいいと思う事ももっと小さい方がいいと思う事もあり、この辺がちょうどいいラインかなぁ、という気はしている。 これより大きいと小さい方がいいと思う機会も増えそう。13インチくらいがせいぜいだなぁ。</p><p>バッテリの減りもまぁ許容範囲かな。たまに使いたい時にバッテリが無い、という状態が生まれてしまうが、 だいたいは運用でカバー出来る。一日使ってPC触っている時に充電でだいたい回せる。 夜寝る時に使っていてそのまま寝て朝起きて朝食の時も使って、そのあと仕事始める時に充電して昼飯くらいには満タンになっている。 このあとは充電しないでそのまま翌日まで持つ感じだ。 朝食のあとにすぐに持って出かけたい時にたまに充電しきれてないシチュエーションはあるが、それでバッテリが無くなった事は無い。</p><p>未だに30Wの充電環境は作れていないが、18Wくらいでも充電は十分早い。 こまめに充電しないと、という感じでは無い。そして充電の速度も作業してて気づけば満タンになってるのでこれで十分かな。</p><p>全体的には値段の分の価値はある良いタブレットだな、と思っている。iPadよりはこちらを使っている事の方が多いな。</p><h3 id="いまいちな所も多いが、大きな本を読むにはやっぱり良い-2026-03-06-金" tabindex="-1"><a class="header-anchor" href="#いまいちな所も多いが、大きな本を読むにはやっぱり良い-2026-03-06-金"><span>いまいちな所も多いが、大きな本を読むにはやっぱり良い 2026-03-06 (金)</span></a></h3><p>5ヶ月くらい使ってみた事になるので感想など。</p><p>まずデメリットは当初から分かってたように2点。</p><ol><li>バッテリの消費が早く充電が遅い</li><li>普段使いにはでかすぎる</li></ol><p>充電が遅いのは充電器の問題だと思うのだが、ちゃんと30Wで充電出来る環境を未だに作れていない。また、なんだかんだで5V 2A程度で充電する機会が多く、すると遅さが目立つ。 バッテリの消費の速さと相まって結構バッテリを気にするデバイスになってしまっている。 <a href="./KindleFire.html">KindleFire</a>Maxの方が減りはだいぶ少なく感じる（向こうの方が充電は遅い気もするが）。</p><p>そして大きさだが、本を読むのにはもっと大きい方がいいとすら思う事も多いが、一方でyoutubeとか見るには大きすぎていまいち、という印象だ。 100均のタブレットスタンドとかだと安定が悪い事も多く、そういう周辺のグッズ的な問題も大きい。youtubeを見るには、大きいメリットよりも取り回しの悪さが目立つ。 持ち歩く時も大きくてかさばる。結構違うもんだな、と思うくらいかさばる。</p><p>ただ今回のエントリを書こうと思ったきっかけでもあるが、<a href="./【書籍】ギャノング生理学.html">【書籍】ギャノング生理学</a>をLenovoTabP12とiPad Proで読んでいて、圧倒的にこのタブレットの方がいいな、と思った。 このサイズのカラーの本を読むとなると全然違うな。 iPadで読むのは相当ストレス、というかギャノング生理学はちょっとこのデバイスで読むのは嫌だなぁ、という感じ。LenovoTabP12なら拡大はするけれど、まぁ普通に読める。 大きな本を読むのは自分の人生において結構大切な事なので、この項目が良いのは他のデメリットは埋めて余りある。 値段の分の価値はあったな、と思う。</p><p>そういう訳でバッテリ周りがもう少し改善してくれればなぁ、とは思うが、サイズ的にはこのくらいはデメリットも目立つがメリットが上回るかな、という印象。</p>`,50)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};